# -*- coding: utf-8 -*-
# Batch 2: SAF (South Africa) - 79 items

translations_batch2 = {
    "SAF_war_measures_act_desc": "Kini setelah kita berada dalam kondisi perang, pemerintah harus memiliki wewenang khusus yang dapat dimobilisasi demi menjaga keamanan garis belakang, kelancaran pelabuhan, dan keterjaminan pasokan tentara.",
    "SAF_emergency_workers_desc": "Pemerintah harus mengesahkan undang-undang yang memungkinkan perekrutan kaum perempuan dan warga non-kulit putih ke dalam industri yang mengalami kelangkaan tenaga kerja masa perang.",
    "SAF_csir_desc": "Dewan Riset Ilmiah dan Industri (CSIR) akan menjadi laboratorium yang didanai negara dengan fokus pada penelitian industri. Kumpulkan para pakar terbaik kita untuk memodernisasi pertambangan, pelabuhan, dan manufaktur kita.",
    "SAF_cape_garrison_artillery_desc": "Tanjung Harapan tetap menjadi jalur laut vital bagi banyak negara sekaligus gerbang menuju jantung Afrika Selatan. Perluasan pertahanan pesisir dan artileri garnisun harus menjadi prioritas utama kita.",
    "SAF_reconstitute_the_cape_corps_desc": "Secara historis, kita dapat mengerahkan sebagian penduduk Kulit Berwarna untuk membela Afrika Selatan. Kebijakan ini memang memicu perdebatan, namun akan membebaskan warga kulit putih Afrika Selatan untuk bertugas di seberang lautan.",
    "SAF_expand_the_cape_corps_desc": "Meskipun kita membentuk kembali Korps Cape sebagian besar sebagai pasukan non-kombatan, ancaman invasi mengharuskan kita memberi korps ini sumber daya, pelatihan, dan akses persenjataan yang lebih besar.",
    "SAF_work_for_all_poor_desc": "Warga Afrikaner miskin dari pedesaan membanjiri kota-kota demi mencari nafkah selama beberapa tahun terakhir, dan kita belum banyak membantu mereka. Melalui industrialisasi dan perlindungan akses kerja oleh negara, taraf hidup mereka akan terangkat.",
    "SAF_outlaw_strikes_desc": "Penghentian kerja dan gangguan perburuhan adalah tindakan tidak patriotik di masa krisis. Aksi mogok kerja dengan ini dinyatakan ilegal, dan pemerintah akan memaksa pekerja kembali beroperasi.",
    "SAF_police_windhoek_desc": "Kita memegang mandat atas bekas koloni Jerman di Afrika Barat Daya sejak perang dunia lalu berakhir. Sangat penting bagi kita untuk menjalankan kewajiban mengamankan dan membangun kota utama Windhoek.",
    "SAF_joint_air_training_scheme_desc": "Negara-negara Persemakmuran menghimpun sumber daya dan pengalaman mereka untuk memfasilitasi dan mempercepat pelatihan pilot serta awak udara.",
    "SAF_desert_equipment_desc": "Perang di Afrika Utara membutuhkan perlengkapan khusus; karena pasukan kita dapat dipanggil bertugas di front tersebut, pengadaan dan pasokan peralatan gurun menjadi kebutuhan logistik yang sangat mendesak.",
    "SAF_suppress_the_stormjaers_desc": "Organisasi fasis pro-Jerman Ossewabrandwag (OB) memiliki sayap paramiliter yang meniru milisi sayap kanan Eropa. Mereka merongrong upaya pemerintah dalam merekrut prajurit dan menjalankan kebijakan perang yang terpadu. Satuan Stormjaers harus dibubarkan.",
    "SAF_secure_interests_in_africa_desc": "Uni Afrika Selatan berbatasan dengan sejumlah koloni Inggris yang dapat diserahkan ke bawah administrasi kita. Kita juga harus berupaya mengamankan status mandat kita atas Afrika Barat Daya secara permanen.",
    "SAF_native_laws_amendment_act_desc": "Demi menjamin lapangan kerja bagi populasi Afrikaner, kita harus membatasi permukiman warga kulit hitam Afrika Selatan di perkotaan. Hanya mereka yang telah lama menetap di kotamadya yang berhak memiliki izin tinggal.",
    "SAF_encourage_segregation_desc": "Kita harus mempertegas pemisahan hukum antaretnis demi memperkokoh dominasi politik dan persatuan kelas penguasa kita.",
    "SAF_abandon_westminster_desc": "Peralihan jalur laut ke Terusan Suez serta pengalaman pahit Perang Boer telah menempa identitas Afrika Selatan yang terpisah dari Dominion lainnya. Kita harus menjauhkan diri dari Raja Inggris dan merintis jalan kedaulatan kita sendiri.",
    "SAF_support_the_afrikaner_broederbond_desc": "Afrikaner Broederbond terus menggalang dukungan demi memperjuangkan aspirasi bangsa Afrikaner dan pemisahan ras yang lebih ketat. Memori pahit penindasan Inggris semasa Perang Boer masih membekas, dan Broederbond dapat membantu membentuk Afrika Selatan yang baru.",
    "SAF_support_ossewabrandwag_desc": "Paramiliter fasis Ossewabrandwag harus diberdayakan sebagai benteng pertahanan dalam meredam agitasi asing dan pemberontakan domestik yang menargetkan kelas penguasa.",
    "SAF_celebrate_the_great_trek_desc": "Satu abad lalu, para leluhur Afrikaner kita memisahkan diri dari cengkeraman kolonial Inggris dan mendirikan negara Boer di timur laut. Semangat pantang menyerah mereka melambangkan keteguhan nilai luhur Afrika Selatan.",
    "SAF_voortrekker_monument_desc": "Monumen bagi kaum Voortrekker yang menempuh Perjalanan Akbar (Groot Trek) akan mengobarkan kembali jiwa kebangsaan dan persatuan di masa-masa penuh ujian ini.",
    "SAF_support_nazification_of_south_west_africa_desc": "Sebagai bekas koloni Jerman, sudah sepantasnya kita mendorong perkembangan gagasan-gagasan politik Jerman di wilayah Afrika Barat Daya.",
    "SAF_support_the_german_coup_desc": "Pemerintah Jerman telah lama memandang Afrika Selatan sebagai ladang pengaruh strategis sejak abad lalu. Masa depan kita berada di pihak Reich, bukan Imperium Britania; mari lanjutkan rencana untuk menggulingkan rezim saat ini.",
    "SAF_reclaim_boer_colonies_desc": "Bekas wilayah Boer di Transvaal dan sekitarnya secara sah merupakan hak milik mutlak para pewaris merdeka dari bangsa pelopor tersebut.",
    "SAF_commemorate_the_battle_of_blood_river_desc": "Pada tahun 1838, benteng kereta pedati pemukim Boer berhasil memukul mundur puluhan ribu laskar Zulu dan melumpuhkan kekuatan mereka di Natal. Ini adalah bukti nyata kebenaran perjuangan suci kita.",
    "SAF_german_scientists_desc": "Para ilmuwan Jerman termasuk yang terbaik di dunia dan memiliki banyak pengetahuan maju untuk dibagikan kepada kita.",
    "SAF_support_axis_interests_desc": "Negara-negara Poros memiliki tekad dan ideologi yang mampu membantu Afrika Selatan menegakkan martabatnya di panggung internasional. Kita harus memberikan dukungan diplomatik penuh.",
    "SAF_a_king_for_our_people_desc": "Afrika Selatan berhak memiliki rajanya sendiri, dan untungnya ada pangeran wangsa Windsor yang tengah terasing. Mantan Raja Edward VIII, Adipati Windsor, dapat dinobatkan ke atas takhta kita.",
    "SAF_empower_the_workers_desc": "Kita adalah negeri kaum tambang dan petani. Kaum pekerja Afrika Selatan adalah satu-satunya representasi sejati dari kehendak seluruh bangsa.",
    "SAF_support_spain_desc": "Fasisme kian merajalela di Eropa, dan kita dapat menghentikannya di Spanyol—atau setidaknya memperlambat penyebarannya. Pasukan dan perbekalan militer harus dikirim demi membela perjuangan Republik.",
    "SAF_repeal_the_native_representation_act_desc": "Diskriminasi rasial bertentangan dengan nilai-nilai revolusi rakyat di Afrika Selatan. Hak suara warga kulit hitam harus dipulihkan dalam daftar pemilih umum dan diberi hak politik setara.",
    "SAF_burn_the_kings_portraits_desc": "Tumbangkan Keluarga Kerajaan! Tindakan simbolis ini akan menegaskan secara terbuka pemutusan total kita dari takhta penjajah asing.",
    "SAF_join_comintern_desc": "Uni Soviet telah berdiri di garda terdepan dalam membela kaum buruh melawan fasisme. Kita akan bergabung ke dalam aliansi perkasa mereka.",
    "SAF_support_the_world_revolution_desc": "Satu-satunya cara agar kaum buruh meraih kemenangan adalah menyatukan seluruh penjuru dunia dalam satu derap langkah. Revolusi harus bersifat universal, dan oleh karenanya, harus disebarluaskan.",
    "SAF_equal_opportunity_employment_desc": "Jika kita ingin mengangkat derajat kaum pekerja di negeri kita, kita harus memulainya dengan memastikan semua buruh diperlakukan setara, tanpa memandang warna kulit.",
    "SAF_demand_madagascar_desc": "Dengan perubahan drastis situasi di Eropa, sudah saatnya meninjau ulang seluruh sistem kolonialisme. Mengapa Madagaskar harus terus terbelenggu pada imperium yang tengah runtuh?",
    "SAF_invite_soviet_advisers_desc": "Jika kita hendak menyokong Uni Soviet dalam memperjuangkan pembebasan buruh sedunia, kita harus meningkatkan mutu militer kita dengan belajar langsung dari mereka.",
    "SAF_south_african_soviet_research_treaty_desc": "Setelah memetik banyak pelajaran berharga dari kawan-kawan Soviet kita, saatnya memperdalam kemitraan ini dengan menandatangani perjanjian riset bilateral resmi.",
    "SAF_anti_colonialist_crusade_desc": "Kolonialisme merupakan jantung dari sistem imperialisme yang menindas kaum tertindas sedunia. Kita berada pada posisi unik untuk menghancurkan sistem itu dan membebaskan rakyat Afrika dari eksploitasi berabad-abad.",
    "SAF_Union_of_the_African_People_desc": "Sekian lama rakyat Afrika tidak memiliki suara dalam menentukan takdir mereka sendiri. Masa-masa kelam itu telah berakhir. Kita akan membentuk faksi perkasa yang mampu menangkis segala upaya kaum revanchis dunia. Afrika akan bebas dari kolonialisme.",
    "SAF_liberate_portugese_desc": "Koloni Angola dan Mozambik berbatasan langsung dengan tanah air kita. Sudah saatnya mengakhiri penghisapan dan penindasan atas rakyat mereka.",
    "SAF_liberate_british_desc": "Imperium Britania adalah contoh kolonialisme paling eksploitatif dalam sejarah manusia. Kita akan mengakhirinya untuk selamanya.",
    "SAF_liberate_belgian_desc": "Kongo Belgia dikenal luas sebagai salah satu babak eksploitasi dan penindasan paling kejam. Kita akan menuliskan babak penutup bagi kisah tirani tersebut.",
    "SAF_south_african_railways_desc": "Perusahaan Kereta Api Afrika Selatan perlu diperluas. Kelompok pemuda dapat dilatih di sana dan dibekali keterampilan teknis untuk membangun negeri maupun bertugas di luar negeri.",
    "SAF_expand_the_mining_industry_desc": "Kekayaan mineral Afrika Selatan melegenda, dan kita baru saja mulai mengeksploitasi cadangan emas, kromium, dan platinum yang melimpah di perut bumi kita.",
    "SAF_heavy_engineering_desc": "Sangat penting bagi Afrika Selatan untuk terus menguasai teknik rekayasa modern. Meski basis industri kita terbatas, investasi pada alat berat dan permesinan akan mempercepat kita menyamai negara maju.",
    "SAF_infrastructure_effort_desc": "Sebagian besar wilayah Afrika Selatan masih berupa pedesaan yang belum terjamah. Jalur jalan raya dan rel kereta api tambahan akan mengalirkan hasil bumi ke pelabuhan-pelabuhan utama kita.",
    "SAF_armament_effort_desc": "Afrika Selatan relatif aman dari ancaman invasi langsung, namun terpisah jauh dari sekutunya. Sangat mendesak untuk mengembangkan industri persenjataan mandiri agar persatuan kita tak pernah tanpa pertahanan.",
    "SAF_south_african_steel_desc": "Kita memiliki batu bara dan bijih besi; kini kita memiliki alasan kuat. Perluasan pabrik baja Iscor di Pretoria akan menyediakan pelat baja tebal yang mutlak dibutuhkan untuk persenjataan modern.",
    "SAF_pretoria_arms_desc": "Pabrik baja Pretoria sebelumnya berfokus pada pelat berat. Namun dengan tambahan perkakas mesin, kita dapat mengonversi sebagian pabrik menjadi pusat pembuatan senjata ringan.",
    "SAF_expand_the_rand_mines_desc": "Tambang Rand termasuk tambang emas terdalam di dunia—bahkan sejak era teknologi abad ke-19. Kini kemampuan kita berlipat ganda; mari menggali lebih dalam dan manfaatkan sepenuhnya kekayaan ini!",
    "SAF_fund_the_university_of_south_africa_desc": "Universitas Afrika Selatan di Pretoria adalah salah satu institusi pendidikan terbaik di benua ini. Melalui investasi terarah, kita dapat memupuk cendekiawan lokal tanpa harus bergantung pada pendidikan di luar negeri.",
    "SAF_establish_the_atomics_energy_board_desc": "Senjata atom akan menjadi lompatan militer terbesar sejak penemuan bubuk mesiu, belum lagi manfaat energi damainya. Himpun ilmuwan terkemuka kita untuk meneliti pemanfaatan atom.",
    "SAF_the_cape_defense_institute_desc": "Kini setelah Afrika Selatan berdaulat penuh, kita tidak lagi mendapatkan cetak biru dan prototipe canggih dari Inggris. Kita harus memastikan diri tetap unggul dari musuh dan tidak tertinggal dalam teknologi.",
    "SAF_defense_collaboration_initiative_desc": "Inggris telah membuktikan manfaat pertukaran riset ilmiah antarsekutu dekat. Seluruh faksi kita akan mampu melaksanakan litbang perang secara efisien jika kita mengoordinasikan langkah ini bersama.",
    "SAF_special_service_battalion_desc": "Afrika Selatan dipenuhi pemuda pengangguran yang butuh arahan produktif. Batalion Dinas Khusus akan menanamkan kedisiplinan dan keterampilan organisasi militer yang sangat dibutuhkan.",
    "SAF_improve_the_three_oh_three_desc": "Pasukan Afrika Selatan akan bertempur di berbagai medan dan iklim; senapan Lee-Enfield beruntung sangat fleksibel untuk dimodifikasi. Kaliber amunisi .303 dapat disesuaikan demi memaksimalkan daya tembak di garis depan.",
    "SAF_q_services_corps_desc": "Korps Dinas Perbekalan (Q Services Corps) akan menjadi otoritas terpusat yang bertanggung jawab atas logistik dan perbekalan tentara reguler, mendistribusikan bahan bakar, ransum, amunisi, dan seragam.",
    "SAF__south_african_military_college_desc": "Afrika Selatan harus memiliki akademi militer yang setara dengan West Point di Amerika Serikat demi melahirkan korps perwira profesional yang setia kepada persatuan negara.",
    "SAF_expand_the_south_african_artillery_desc": "Korps artileri telah dipersatukan pada tahun 1934. Kini telah tiba saatnya melipatgandakan kekuatan personel dan daya gempurnya.",
    "SAF_sa_engineer_corps_desc": "Korps Zeni Afrika Selatan hanya beranggotakan sekitar 600 prajurit berseragam. Hal ini tidak dapat diterima dalam tentara modern. Kita membutuhkan lebih banyak personel terlatih untuk tugas krusial ini.",
    "SAF_equipment_effort_desc": "Kita tidak boleh mengabaikan pengadaan perlengkapan pendukung tentara kita. Senjata dan tank memang penting, namun seragam, radio komunikasi, kotak perbaikan, dan alat logistik lainnya sama krusialnya.",
    "SAF_south_african_special_forces_desc": "Afrika Selatan membutuhkan satuan komando mandiri untuk menjalankan misi-misi paling berbahaya di medan tempur yang sulit dijangkau.",
    "SAF_mechanization_effort_desc": "Perang mekanis dan bermotor telah tiba. Perjalanan akbar masa depan akan dipandu oleh deru armada rantai dan kendaraan tempur lapis baja beroda.",
    "SAF_armor_effort_desc": "Tank telah berkembang pesat meninggalkan sosok lamban dari era perang dunia sebelumnya. Riset dan doktrin kavaleri lapis baja kita tidak boleh tertinggal dari kawan maupun lawan.",
    "SAF_commit_to_the_five_year_plan_desc": "Kita telah menyusun Rencana Lima Tahun untuk modernisasi dan ekspansi angkatan udara Afrika Selatan. Pemerintah harus berkomitmen penuh agar target strategis ini tidak meleset.",
    "SAF_improve_the_hawker_hartbees_desc": "Hawker Hartbees yang kita miliki memang bukan pesawat paling modern di dunia, namun kita akan memaksimalkannya. Peningkatan mekanik dan jam terbang pilot akan mendongkrak performa pesawat sayap ganda ini.",
    "SAF_replace_the_blenheim_desc": "Bristol Blenheim telah mengabdi dengan baik sebagai pengebom ringan bagi RAF dan Dominion. Namun kini saatnya beralih ke pesawat yang lebih kokoh dengan daya jelajah lebih jauh.",
    "SAF_perfect_the_cab_rank_technique_desc": "Taktik antrean serang \"Cab-Rank\" mengerahkan formasi pengebom untuk menghantam sasaran secara bertubi-tubi dalam garis beruntun, memberikan tekanan tanpa henti kepada musuh.",
    "SAF_desert_air_force_desc": "Langit padang pasir begitu terik, dan badai pasir menuntut perawatan ekstra bagi mesin pesawat kita. Ketahanan tempur berharga dapat ditempa di lingkungan ekstrem ini.",
    "SAF_secure_the_cape_sea_route_desc": "Jika Terusan Suez jatuh ke tangan musuh, rute Tanjung Harapan akan kembali menjadi satu-satunya gerbang laut menuju belahan Timur. Amankan rute ini berapapun harganya!",
    "SAF_retain_experienced_pilots_desc": "Kerap kali penerbang berpengalaman kita berpindah ke RAF alih-alih memperkuat angkatan sendiri. Kita harus mempertahankan para pilot andal ini di tanah air untuk mendidik dan menginspirasi kader penerbang muda kita.",
    "SAF_seaward_defence_force_desc": "Pasukan Pertahanan Lautan (Seaward Defence Force) telah menjadi garda bahari kita selama dua dasawarsa. Alokasi anggarannya harus dilipatgandakan demi memperkokoh armada kita.",
    "SAF_protect_the_trade_desc": "Perang lalu membuktikan betapa vitalnya konvoi dan kapal pengawal. Afrika Selatan terletak di persimpangan rute dagang utama dunia dan harus menjamin keselamatan kapal kargo hingga ke tujuan.",
    "SAF_disrupt_the_trade_desc": "Perang lalu membuktikan betapa rentannya jalur pasokan laut. Posisi Afrika Selatan sangat ideal untuk mencegat dan menenggelamkan konvoi perkapalan musuh.",
    "SAF_expand_the_simons_town_base_desc": "Simon's Town di Tanjung Harapan telah menjadi pangkalan laut terpenting di Afrika bagian selatan sejak tahun 1790-an. Pangkalan ini harus diperluas agar mampu menampung kapal-kapal perang berbobot besar.",
    "SAF_anti_submarine_tactics_desc": "Kapal selam musuh mengancam pelayaran yang melintasi Tanjung Harapan. Kita harus melacak, memburu, dan menenggelamkan mereka.",
    "SAF_submarine_warfare_desc": "Konvoi dagang musuh terus memanfaatkan jalur pelayaran Tanjung Harapan. Kita akan menyerang dan memusnahkan mereka dari kedalaman laut.",
    "SAF_prepare_overseas_offensive_desc": "Dengan ribuan mil garis pantai, Afrika Selatan sangat ideal untuk melatih prajurit dalam operasi amfibi. Ini adalah taktik yang sangat menantang, namun prajurit kita siap menguasainya.",
    "SAF_strengthen_the_cape_garrison_artillery_desc": "Meriam garnisun di Tanjung Harapan harus dimodernisasi dan diperbanyak jumlahnya demi melindungi perairan Tanjung dari serangan armada musuh."
}

if __name__ == '__main__':
    print(f"Batch 2 contains {len(translations_batch2)} translations.")
